POST = {'app/src/main/assets/shaders/motionv2/gainmap.glsl': '0a8cf6f31965da396546369baa7cc019c1a5a06002a3ad23e00e4bd27e17730f',
 'app/src/main/assets/shaders/motionv2/rcd26489_green_rb.glsl': '27dc84526165f690b458dd1c325416416861d9fe2a795e500f77970fd018da97',
 'app/src/main/assets/shaders/motionv2/rcd26489_opposite.glsl': 'd2e38f2e7a6249bcf345805fe191bbe81ae4f4e709c793ccf6536489888ebb73',
 'app/src/main/assets/shaders/motionv2/rcd26489_populate.glsl': 'faea810406557be9495fb62e60f2693e7a6a8ed33724a8d1648bbad3e1059030',
 'app/src/main/java/com/particlesdevs/photoncamera/capture/CaptureController.java': '268a03d9eb00a76e45389a23046dc481950f8dcd7f1e6369e9fe8a2f969408a0',
 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2RcdDemosaic.java': 'e6009517ea4a698c5899ff1dc37c3684916677969f0cf01ed9d8b49b29e2500a',
 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Render.java': '993fd81603120afa31b67ac54f9b8f5e80c67b26169485cad2af360888238d54'}
BLOBS = {'app/src/main/assets/shaders/motionv2/gainmap.glsl': '',
 'app/src/main/assets/shaders/motionv2/rcd26489_green_rb.glsl': '',
 'app/src/main/assets/shaders/motionv2/rcd26489_opposite.glsl': '',
 'app/src/main/assets/shaders/motionv2/rcd26489_populate.glsl': '',
 'app/src/main/java/com/particlesdevs/photoncamera/capture/CaptureController.java': '',
 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2RcdDemosaic.java': '',
 'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Render.java': ''}

KERNEL = [
    0.042229693589, 0.070339090351, 0.103129012812, 0.133097613729,
    0.151204589518, 0.151204589518, 0.133097613729, 0.103129012812,
    0.070339090351, 0.042229693589,
]

def sha_bytes(data): return hashlib.sha256(data).hexdigest()
def sha_file(path): return sha_bytes(path.read_bytes())

def transfer(weights, frequency):
    center=(len(weights)-1)*0.5
    return abs(sum(w*cmath.exp(-2j*math.pi*frequency*(i-center)) for i,w in enumerate(weights)))

def self_test():
    # 2.5 EV is physical acquisition headroom only.
    ev=2.5
    divisor=2.0**ev
    target=1.0/divisor
    tol_ev=0.35
    tol=2.0**tol_ev
    deepest_scale=1.0/(target/tol)
    assert abs(divisor-5.656854249492381)<1e-12
    assert abs(target-0.1767766952966369)<1e-12
    assert deepest_scale<8.0  # existing shortToNormalScale clamp remains sufficient

    # 26494 4-tap box leaves ~65% amplitude at the new 1/4-map Nyquist.
    box=[0.25]*4
    h_box=transfer(box,1.0/8.0)
    h_new=transfer(KERNEL,1.0/8.0)
    h_high=transfer(KERNEL,3.0/16.0)
    h_pass=transfer(KERNEL,1.0/16.0)
    assert h_box>0.65
    assert all(w>0.0 for w in KERNEL)
    assert abs(sum(KERNEL)-1.0)<2e-11
    assert max(abs(a-b) for a,b in zip(KERNEL,reversed(KERNEL)))<1e-15
    assert h_new<0.10 and h_high<0.05 and h_pass>0.60

    # Shared balanced fallback has no color-dependent degree of freedom.
    shared=1.37
    for wb,gain in [(1.9,2.2),(1.0,1.0),(1.55,1.73),(2.35,1.42)]:
        calc=shared*wb/gain
        assert abs(calc*gain/wb-shared)<1e-12

    # Full-file blobs are deterministic and match declared POST hashes.
    for rel,b64 in BLOBS.items():
        data=gzip.decompress(base64.b64decode(b64))
        assert sha_bytes(data)==POST[rel]

    print('26495 SELF-TEST PASS')
    print(f'exposureEv={ev:.6f} divisor={divisor:.12f} targetRatio={target:.12f} deepestAcceptedScale={deepest_scale:.6f}')
    print(f'gainmapH_box4_at_newNyquist={h_box:.6f} gainmapH_gaussian10_at_newNyquist={h_new:.6f} H_3over16={h_high:.6f} H_1over16={h_pass:.6f}')

def apply(root):
    root=Path(root)
    for rel,expected in PRE.items():
        p=root/rel
        if not p.is_file(): raise SystemExit(f'missing exact 26494 target: {rel}')
        actual=sha_file(p)
        if actual!=expected: raise SystemExit(f'26494 target hash mismatch: {rel} actual={actual} expected={expected}')

    for rel,b64 in BLOBS.items():
        data=gzip.decompress(base64.b64decode(b64))
        p=root/rel
        p.write_bytes(data)
        actual=sha_file(p)
        if actual!=POST[rel]: raise SystemExit(f'post-write hash mismatch: {rel}')

    # Semantic invariants on the exact generated source.
    capture=(root/'app/src/main/java/com/particlesdevs/photoncamera/capture/CaptureController.java').read_text()
    populate=(root/'app/src/main/assets/shaders/motionv2/rcd26489_populate.glsl').read_text()
    opposite=(root/'app/src/main/assets/shaders/motionv2/rcd26489_opposite.glsl').read_text()
    greenrb=(root/'app/src/main/assets/shaders/motionv2/rcd26489_green_rb.glsl').read_text()
    host=(root/'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2RcdDemosaic.java').read_text()
    gain=(root/'app/src/main/assets/shaders/motionv2/gainmap.glsl').read_text()
    render=(root/'app/src/main/java/com/particlesdevs/photoncamera/processing/opengl/postpipeline/MotionV2Render.java').read_text()

    assert capture.count('applyMotion26486ExplicitShortCaptureIfNeeded(')==2  # definition + one caller
    assert capture.count('applyMotion26480ExplicitShortCaptureIfNeeded()')==1  # legacy definition only
    assert capture.count('IRIS_26495_PHYSICAL_SHORT_HEADROOM_2P5EV')==1
    assert capture.count('IRIS_26495_CLAMP_AWARE_SHORT_RADIOMETRY')==1
    assert '5.656854249492381' in capture
    assert 'requestedRatioMin' in capture and 'actualHeadroomEv' in capture

    assert populate.count('IRIS_26495_CENSORED_LUMA_ONLY_CHROMA_AUTHORITY')==1
    assert 'constrainedSamePhaseBalanced' not in populate
    assert populate.count('constrainedSharedNeutralBalanced')==2
    assert opposite.count('IRIS_26495_RCD_OPPOSITE_PROVENANCE_WEIGHT')==1
    assert greenrb.count('IRIS_26495_RCD_GREEN_SITE_PROVENANCE_WEIGHT')==1
    assert host.count('setTexture("HighlightProvenance"')==3  # populate + opposite + green-site chroma
    assert host.count('censoredOpponentColorAuthority=zero')==1

    assert gain.count('IRIS_26495_BANDLIMITED_UHDR_GAINMAP')==1
    assert gain.count('KERNEL[')==3
    assert 'FILTER_TAPS = 10' in gain and 'DOWNSAMPLE = 4' in gain
    assert render.count('preDecimationBandlimit=positiveGaussian10x10Sigma2p8')==1
    assert 'GAINMAP_DOWNSAMPLE = 4' in render

    print('26495 TRANSFORM PASS')

if __name__=='__main__':
    if len(sys.argv)==2 and sys.argv[1]=='--self-test': self_test()
    elif len(sys.argv)==2:
        self_test(); apply(sys.argv[1])
    else: raise SystemExit('usage: transform_26495_integrated_hdr_evidence_provenance_uhdr_aa_v1.py --self-test | <repo-root>')
